package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.PointDirectory
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.BitSet
import java.util.concurrent.atomic.AtomicLong

/** Diagnostic field reads only. No AP query, materialization, interner or mutation. */
internal object PointAdmissionObservation {
    private val transactions = AtomicLong()
    fun next(): Long = transactions.incrementAndGet()

    private fun field(owner: Any, name: String): Any? {
        var type: Class<*>? = owner.javaClass
        while (type != null) {
            try {
                return type.getDeclaredField(name).run { isAccessible = true; get(owner) }
            } catch (_: NoSuchFieldException) { type = type.superclass }
        }
        error("Missing diagnostic field $name")
    }

    @Suppress("UNCHECKED_CAST")
    fun bucket(out: LoopPipelineTrace.Fields, core: BlockRunState, node: CommonInst,
               premise: PremiseKey, prefix: String) {
        check(core.config.index == 2 && premise.isZero)
        val store = core.edges
        // B2 point storage has flowBacked=false. Do not enter a packed decoder.
        check(field(store, "packed") == null)
        val points = field(store, "points") as PointDirectory<CommonInst>
        val index = points.index(node) // Immutable point-directory lookup only.
        out.number("$prefix.pointIndex", index)
        val reaches = field(store, "reach") as Map<PremiseKey, Array<BitSet>>
        val bits = reaches[premise]
        out.flag("$prefix.reachNormal", bits?.get(0)?.get(index) == true)
        out.flag("$prefix.reachDemand", bits?.get(1)?.get(index) == true)
        val rows = (field(store, "groups") as Map<PremiseKey, Any>)[premise]
        out.flag("$prefix.rowsPresent", rows != null)
        if (rows == null) { out.number("$prefix.headerCount", 0); return }
        val initial = field(rows, "initial") as InitialAp?
        out.flag("$prefix.hasCompactInitial", initial != null)
        initial?.let { out.premise("$prefix.compactInitial", it) }
        for (name in listOf("normal", "demand", "protectedNormal", "protectedDemand")) {
            out.flag("$prefix.compact.$name", (field(rows, name) as BitSet?)?.get(index) == true)
        }
        val full = field(rows, "full") as Array<Any?>?
        val group = full?.get(index)
        out.flag("$prefix.fullGroupPresent", group != null)
        if (group == null) { out.number("$prefix.headerCount", 0); return }
        val reach = field(group, "reach") as BooleanArray
        out.flag("$prefix.groupReachNormal", reach[0])
        out.flag("$prefix.groupReachDemand", reach[1])
        var count = 0
        for (name in listOf("flow", "taint")) {
            val owners = field(group, name) as Map<Any, Any>
            for (owner in owners.entries.sortedBy { it.key.toString() }) {
                val trees = field(owner.value, "trees") as Array<MutableList<*>>
                for (layer in trees.indices) for (value in trees[layer]) {
                    check(count < 128)
                    out.facts("$prefix.header.$count", value as Facts)
                    count++
                }
            }
        }
        out.number("$prefix.headerCount", count)
    }
}

