// PREPARED ONLY. Root may run only after every real-project campaign command is terminal.
def prep = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/concrete-demand-guidance-design-20261106/storage-validation/forward3-full-capture')
def pins = new groovy.json.JsonSlurper().parse(new File(prep, 'provider-pins.json'))
def nativePins = new groovy.json.JsonSlurper().parse(new File(prep, 'native-source-pins.json'))
def verifyCaptureInputs = {
  def localPins = new groovy.json.JsonSlurper().parse(new File(prep, 'prepared-input-pins.json'))
  (pins.jars + nativePins.sources + localPins.files).each { pin ->
    def file = new File(pin.path)
    if (!file.isFile()) throw new GradleException('Missing pinned capture input: ' + pin.path)
    def actual = java.security.MessageDigest.getInstance('SHA-256').digest(file.bytes).encodeHex().toString()
    if (actual != pin.sha256) throw new GradleException('Pinned capture input changed: ' + pin.path)
  }
}

allprojects { p ->
  if (p.name == 'opentaint-dataflow' && p.projectDir.name == 'opentaint-dataflow') {
    p.afterEvaluate {
      def probe = p.sourceSets.create('forward3FullCaptureProbe')
      probe.java.setSrcDirs([])
      probe.resources.setSrcDirs([])
      p.kotlin.sourceSets.getByName('forward3FullCaptureProbe').kotlin.setSrcDirs([new File(prep, 'src')])
      probe.compileClasspath = p.sourceSets.main.output + p.sourceSets.test.output + p.configurations.testCompileClasspath
      def classes = new File(prep, 'compiled')
      probe.output.classesDirs.setFrom(classes)
      p.tasks.named('compileForward3FullCaptureProbeKotlin') {
        dependsOn p.tasks.named('testClasses')
        doFirst { verifyCaptureInputs() }
        destinationDirectory.set(classes)
        compilerOptions.jvmTarget.set(p.tasks.named('compileKotlin').get().compilerOptions.jvmTarget)
        compilerOptions.moduleName.set('opentaint-dataflow')
        compilerOptions.freeCompilerArgs.add('-Xfriend-paths=' + [
          p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile,
          p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile
        ].collect { it.absolutePath }.join(','))
      }
      p.tasks.register('runForward3FullSharedLoopCapture', JavaExec) {
        dependsOn p.tasks.named('compileForward3FullCaptureProbeKotlin')
        classpath = probe.output + p.sourceSets.test.runtimeClasspath + p.files(pins.jars.collect { new File(it.path) })
        mainClass.set('org.opentaint.dataflow.bidi.SharedLoopPointAdmissionSnapshotProbe')
        jvmArgs '-Xmx1g', '-XX:ActiveProcessorCount=1'
        timeout.set(java.time.Duration.ofSeconds(20))
        systemProperty 'org.opentaint.bidi.run1MarkMode', 'FULL'
        def traceMethods = [mapper: 'Loop direct T branch mapper [context]', getterF: 'Loop direct T getter f [context]', getterG: 'Loop direct T getter g [context]', root: 'Loop direct T observer root [context]']
        def selectedTraceMethod = (p.findProperty('forward3LoopTraceMethod') ?: 'mapper').toString()
        if (selectedTraceMethod != 'mapper') throw new GradleException('This full F3 capture selects mapper only')
        systemProperty 'org.opentaint.bidi.loopTraceMethod', traceMethods[selectedTraceMethod]
        def selectedTraceRun = (p.findProperty('forward3LoopTraceRun') ?: '3').toString()
        if (selectedTraceRun != '3') throw new GradleException('This full forward capture is F3 only')
        systemProperty 'org.opentaint.bidi.loopTraceRun', selectedTraceRun
        systemProperty 'org.opentaint.bidi.loopTraceLimit', '4096'
        systemProperty 'logback.configurationFile', new File(prep, 'logback.xml').absolutePath
        doFirst {
          verifyCaptureInputs()
          if (classpath.files.iterator().next().canonicalFile != classes.canonicalFile)
            throw new GradleException('Fresh compiled capture directory must lead the classpath')
          if (classpath.files.any { it.canonicalPath.startsWith('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/concrete-demand-guidance-design-20261106/storage-validation/post-repair-point-capture/compiled') || it.canonicalPath.startsWith('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/guidance-retention-shared-loop-investigation-20261106/prepared-point-admission-transaction-20261106/compiled') })
            throw new GradleException('Old capture classes must not enter the new runtime')
          new File(prep, 'actual-classpath.txt').text = classpath.files.collect { it.absolutePath }.join('\n') + '\n'
        }
      }
      p.tasks.register('forward3ObservedAlPairMechanism', Test) {
        dependsOn p.tasks.named('compileForward3FullCaptureProbeKotlin')
        testClassesDirs = probe.output.classesDirs
        classpath = probe.output + p.sourceSets.test.runtimeClasspath
        useJUnitPlatform()
        filter { includeTestsMatching 'org.opentaint.dataflow.bidi.ObservedAlPairedDemandMechanismTest' }
        doFirst {
          nativePins.sources.each { pin ->
            def file = new File(pin.path)
            def actual = java.security.MessageDigest.getInstance('SHA-256').digest(file.bytes).encodeHex().toString()
            if (actual != pin.sha256) throw new GradleException('Pinned native source changed: ' + pin.path)
          }
        }
        maxParallelForks = 1
        maxHeapSize = '1g'
        jvmArgs '-XX:ActiveProcessorCount=1', '-Dopentaint.bidi.run1MarkMode=FULL'
        timeout.set(java.time.Duration.ofSeconds(20))
        reports.junitXml.outputLocation.set(new File(prep, 'test-results'))
        reports.html.outputLocation.set(new File(prep, 'test-report'))
      }
    }
  }
}

