gap/NormalStarFlowAdmissionGapTest.kt.text:
package org.opentaint.dataflow.bidi

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.fixtures.StoreFixtures
import org.opentaint.dataflow.bidi.store.*
import kotlin.test.*

/** EXTERNAL PREPARATION ONLY. Not injected into the real program. Root compiles/runs.
 * Current rejection and ordinary transfer validity are independent observations;
 * these tests neither select an admission change nor prove program recovery.
 */
class NormalStarFlowAdmissionGapTest {
    private val f = StoreFixtures()
    private val m = f.manager
    private val ops = f.ops
    private val q = AccessPathBase.Argument(0)
    private val gotF = AccessPathBase.LocalVar(1)
    private val ret = AccessPathBase.Return
    private val first = f.field("f")
    private val second = f.field("g")
    private val t = MarkSlot.Concrete(f.mark("T"))
    private val flow = MarkSlot.STAR
    private val policy = RestrictedInitialPolicy(3, 2, Direction.FORWARD, m.marks)
    private val mode = ApMode(false, Direction.FORWARD, 2, MarkMode.FULL)

    @Test fun `current same-head ANY demand rejects NORMAL STAR FLOW`() {
        val demand = f.pattern(q, listOf(second), Tail.ANY, flow)
        val actual = f.fact(q, listOf(second), Tail.STAR, flow, layer = Layer.NORMAL)
        assertEquals(Layer.NORMAL, actual.layer)
        assertEquals(Tail.STAR, (actual as FlowTree).tail)
        assertNull(policy.emitAdmission(demand, ops.leaves(actual).single(), actual.layer))
        val snapshot = DemandStore.Builder(m).apply {
            add(f.method, DemandPattern(demand, f.pattern(ret, tail = Tail.ANY, mark = flow)))
        }.build()
        assertTrue(snapshot.initials(f.method, actual, policy).isEmpty())
    }

    private fun readAll(actual: Facts, original: PremiseKey, from: AccessPathBase,
                        to: AccessPathBase, field: Int): List<Facts> {
        val edge = PathEdge(PathFact(from, listOf(field), Tail.STAR, flow),
            PathFact(to, emptyList(), Tail.STAR, flow), ExclusionSet.Empty)
        val out = CollectingOut()
        ops.applyEdge(actual, original, edge, statementEdge = true, mode = mode, out = out)
        assertTrue(out.markRequests.isEmpty())
        return out.results
    }

    private fun read(actual: Facts, original: PremiseKey, from: AccessPathBase,
                     to: AccessPathBase, field: Int): Facts = readAll(actual, original, from, to, field).single()

    @Test fun `ordinary read transfers STAR FLOW and exact T suffixes without demotion`() {
        val metadata = f.fact(gotF, listOf(second), Tail.STAR, flow, layer = Layer.NORMAL)
        val flowOriginal = m.initial(f.pattern(gotF, listOf(second), Tail.STAR, flow))
        val metadataResult = read(metadata, flowOriginal, gotF, ret, second)
        assertEquals(Layer.NORMAL, metadataResult.layer)
        assertEquals(setOf(f.pattern(ret, tail = Tail.STAR, mark = flow)), ops.leaves(metadataResult).toSet())

        val exact = f.fact(q, listOf(first, second), Tail.EXACT, t, layer = Layer.NORMAL)
        val original = m.initial(f.pattern(q, listOf(first, second), Tail.EXACT, t))
        val afterF = read(exact, original, q, gotF, first)
        assertEquals(Layer.NORMAL, afterF.layer)
        assertEquals(setOf(f.pattern(gotF, listOf(second), Tail.EXACT, t)), ops.leaves(afterF).toSet())
        val afterG = read(afterF, original, gotF, ret, second)
        assertEquals(Layer.NORMAL, afterG.layer)
        assertEquals(setOf(f.pattern(ret, tail = Tail.EXACT, mark = t)), ops.leaves(afterG).toSet())
        assertNull((afterG as TaintTree).nonSubsumable)
    }

    @Test fun `getter g does not transfer the wrong first field for FLOW or concrete T`() {
        for ((tail, mark) in listOf(Tail.STAR to flow, Tail.EXACT to t)) {
            val actual = f.fact(gotF, listOf(first), tail, mark, layer = Layer.NORMAL)
            val original = m.initial(f.pattern(gotF, listOf(first), tail, mark))
            assertTrue(readAll(actual, original, gotF, ret, second).isEmpty())
        }
    }
}

