// External fixture only. Root-owned run-native-tests.py is the supported entry point.
def prep = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/concrete-demand-guidance-design-20261106/normal-star-flow-admission-gap')
def pins = new groovy.json.JsonSlurper().parse(new File(prep, 'native-source-seals.json'))
def sha = { File f -> java.security.MessageDigest.getInstance('SHA-256').digest(f.bytes).encodeHex().toString() }
def verifySeals = {
    pins.files.each { pin ->
        if (sha(new File(pin.path)) != pin.sha256) throw new GradleException('Source seal changed: ' + pin.path)
    }
    pins.trees.each { pin ->
        def base = new File(pin.path)
        def files = []
        base.eachFileRecurse(groovy.io.FileType.FILES) { files.add(it) }
        files.sort { a, b -> base.toPath().relativize(a.toPath()).toString() <=> base.toPath().relativize(b.toPath()).toString() }
        def digest = java.security.MessageDigest.getInstance('SHA-256')
        files.each { file ->
            def relative = base.toPath().relativize(file.toPath()).toString()
            digest.update((relative + '\u0000' + sha(file) + '\n').getBytes('UTF-8'))
        }
        if (files.size() != pin.files || digest.digest().encodeHex().toString() != pin.sha256)
            throw new GradleException('Source tree seal changed: ' + pin.path)
    }
}
allprojects { p ->
    if (p.projectDir.canonicalFile == new File('/drive-testcomp/opentaint-go-rules/opentaint-w3/core/opentaint-dataflow-core/opentaint-dataflow').canonicalFile) {
        p.afterEvaluate {
            def fixture = p.sourceSets.create('normalStarFlowGap')
            fixture.java.setSrcDirs([])
            fixture.resources.setSrcDirs([])
            def kotlinSource = p.kotlin.sourceSets.getByName('normalStarFlowGap').kotlin
            kotlinSource.setSrcDirs([prep])
            kotlinSource.include('NormalStarFlowAdmissionGapTest.kt')
            fixture.compileClasspath = p.sourceSets.main.output + p.sourceSets.test.output + p.configurations.testCompileClasspath
            def output = new File(prep, 'native/compiled')
            fixture.output.classesDirs.setFrom(output)
            p.tasks.named('compileNormalStarFlowGapKotlin') {
                dependsOn p.tasks.named('testClasses')
                destinationDirectory.set(output)
                compilerOptions.jvmTarget.set(p.tasks.named('compileKotlin').get().compilerOptions.jvmTarget)
                compilerOptions.freeCompilerArgs.add('-Xfriend-paths=' + [
                    p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile,
                    p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile
                ].collect { it.absolutePath }.join(','))
                doFirst { verifySeals() }
            }
            p.tasks.register('normalStarFlowAdmissionGapTest', Test) {
                dependsOn p.tasks.named('compileNormalStarFlowGapKotlin')
                testClassesDirs = fixture.output.classesDirs
                classpath = fixture.output + p.sourceSets.test.runtimeClasspath
                useJUnitPlatform()
                filter { includeTestsMatching 'org.opentaint.dataflow.bidi.NormalStarFlowAdmissionGapTest' }
                maxParallelForks = 1
                maxHeapSize = '1g'
                jvmArgs '-XX:ActiveProcessorCount=2'
                timeout.set(java.time.Duration.ofSeconds(20))
                reports.junitXml.outputLocation.set(new File(prep, 'native/test-results'))
                reports.html.outputLocation.set(new File(prep, 'native/test-report'))
                binaryResultsDirectory.set(new File(prep, 'native/binary-results'))
                doFirst {
                    verifySeals()
                    new File(prep, 'native/actual-classpath.txt').text = classpath.files.collect { it.absolutePath }.join('\n') + '\n'
                }
            }
        }
    }
}

